using System;using System.Data;namespace AQOONHUB_SMS.Modules.Finance{public partial class PrintInvoice:System.Web.UI.Page{protected void Page_Load(object s,EventArgs e){if(Session["UserID"]==null)Response.Redirect("~/Modules/Authentication/Login.aspx");if(IsPostBack)return;int id;if(!int.TryParse(Request.QueryString["id"],out id))Response.Redirect("FeeManagement.aspx");FeeRepository r=new FeeRepository();DataTable d=r.GetInvoice(id);if(d.Rows.Count==0)Response.Redirect("FeeManagement.aspx");DataRow x=d.Rows[0];number.Text=Convert.ToString(x["InvoiceNumber"]);student.Text=Convert.ToString(x["StudentName"]);studentCode.Text=Convert.ToString(x["StudentCode"]);classInfo.Text=x["ClassName"]+" · "+x["SectionName"];invoiceDate.Text=Convert.ToDateTime(x["InvoiceDate"]).ToString("dd MMM yyyy");dueDate.Text=Convert.ToDateTime(x["DueDate"]).ToString("dd MMM yyyy");year.Text=Convert.ToString(x["YearName"]);status.Text=Convert.ToString(x["Status"]);subtotal.Text=Convert.ToDecimal(x["Subtotal"]).ToString("N2");discount.Text=Convert.ToDecimal(x["DiscountAmount"]).ToString("N2");total.Text=Convert.ToDecimal(x["TotalAmount"]).ToString("N2");paid.Text=Convert.ToDecimal(x["PaidAmount"]).ToString("N2");balance.Text=Convert.ToDecimal(x["Balance"]).ToString("N2");remarks.Text=Convert.ToString(x["Remarks"]);instructions.Text=Convert.ToString(x["PaymentInstructions"]);prepared.Text=Convert.ToString(x["PreparedBy"]);pay.NavigateUrl="RecordPayment.aspx?invoice="+id;pay.Visible=Convert.ToDecimal(x["Balance"])>0;items.DataSource=r.GetInvoiceItems(id);items.DataBind();}}}
